steps.script:
var PV = load("res://scripts/PlanValidator.gd")
var PM = load("res://scripts/PlanManager.gd")
PM.ensure_user_plans_dir()
var dir = DirAccess.open("user://ai_plans")
if dir != null:
	dir.list_dir_begin()
	var f = dir.get_next()
	while f != "":
		if f.ends_with(".json"):
			dir.remove(f)
		f = dir.get_next()
	dir.list_dir_end()
var fixture = PV.load_plan_file("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json")
var path = "user://ai_plans/%s.json" % PM.slugify(str(fixture.get("name", "")))
var file = FileAccess.open(path, FileAccess.WRITE)
file.store_string(JSON.stringify(fixture, "\t"))
file.close()
return path

# Rows are found BY NAME, not by index. This scenario used to assume the
# browser contained exactly one plan — the fixture it writes — which stopped
# being true the moment PM-10 shipped plans in res://data/ai_plans/. The
# browser was right and the test was wrong. What this scenario is actually
# about is the lifecycle of the user's OWN plan, so it now counts and locates
# user rows and is indifferent to how much content ships alongside them.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Fixture — Recon Stomps rich (all five verbs)":
		break
	item = item.get_next()
if item == null:
	return "fixture row missing"
return "%s|%s|%s|%s|%s|%s" % [item.get_text(0), item.get_text(1), item.get_text(2),
	item.get_text(3), item.get_text(4), item.get_text(5)]

var d = node.get_node("/root/MainMenu/PlanBrowserDialog")
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
if item == null:
	return "no rows"
item.select(0)
d._on_row_selected()
return d.selected_path

# Rows are found BY NAME, not by index. This scenario used to assume the
# browser contained exactly one plan — the fixture it writes — which stopped
# being true the moment PM-10 shipped plans in res://data/ai_plans/. The
# browser was right and the test was wrong. What this scenario is actually
# about is the lifecycle of the user's OWN plan, so it now counts and locates
# user rows and is indifferent to how much content ships alongside them.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Renamed by pm7b":
		break
	item = item.get_next()
return "missing" if item == null else item.get_text(0)

var PM = load("res://scripts/PlanManager.gd")
var r = PM.rename_plan("res://tests/fixtures/ai_plans/fixture_recon_stomps_rich.json", "nope")
return bool(r.get("success", true))

var d = node.get_node("/root/MainMenu/PlanBrowserDialog")
var e = d.entry_for("user://ai_plans/renamed_by_pm7b.json")
return str(e.get("source", ""))

# Rows are found BY NAME, not by index. This scenario used to assume the
# browser contained exactly one plan — the fixture it writes — which stopped
# being true the moment PM-10 shipped plans in res://data/ai_plans/. The
# browser was right and the test was wrong. What this scenario is actually
# about is the lifecycle of the user's OWN plan, so it now counts and locates
# user rows and is indifferent to how much content ships alongside them.
var t = node.get_node("/root/MainMenu/PlanBrowserDialog/PlanBrowserRoot/PlanBrowserTree")
var item = t.get_root().get_first_child()
while item != null:
	if item.get_text(0) == "Renamed by pm7b":
		break
	item = item.get_next()
if item == null:
	return "renamed row missing"
item.select(0)
var d = node.get_node("/root/MainMenu/PlanBrowserDialog")
d._on_row_selected()
return d.selected_path
